{
  "avaliacoes": [
    {
      "id": "Ebbb9e2c7b83b1913",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A drenagem aberta é segregada em ao menos quatro grupos: área classificada, área não classificada, drenagem de hidrocarbonetos classificada e não classificada, e drenagem para overboard.",
          "trechos": [
            "Ebbb9e2c7b83b1913:0:698"
          ],
          "condicoes": [
            "Descrição de arranjo de sistema da unidade retratada na fonte"
          ],
          "limites": [
            "A fonte não explicita critérios formais de classificação perigosa/não perigosa nem se o arranjo é universal para FPSOs"
          ]
        },
        {
          "proposicao": "Nos sistemas de drenagem aberta de áreas classificada e não classificada há coleta em filtro/tanque com compartimento superior para hidrocarboneto sobrenadante e bombeamento do hidrocarboneto separado para o vaso de slop.",
          "trechos": [
            "Ebbb9e2c7b83b1913:0:698"
          ],
          "condicoes": [
            "Aplicável aos dois primeiros sistemas de drenagem mencionados na própria fonte"
          ],
          "limites": [
            "A fonte não informa capacidade, lógica de controle, alarmes ou limites operacionais"
          ]
        },
        {
          "proposicao": "A drenagem para overboard inclui água de chuva e de dilúvio, água do compartimento inferior dos tanques de drenagem aberta, água tratada nos flotadores e outros rejeitos; já a drenagem fechada inclui o vaso de slop, que recebe rejeito oleoso contínuo e o retorna ao sistema de produção de óleo por bombas.",
          "trechos": [
            "Ebbb9e2c7b83b1913:698:1397"
          ],
          "condicoes": [
            "Conforme a filosofia descrita na fonte para separar correntes aquosas de correntes oleosas"
          ],
          "limites": [
            "A fonte não descreve intertravamentos para evitar interligação indevida nem critérios de aceitação ambiental além da destinação indicada"
          ]
        }
      ]
    },
    {
      "id": "E004f889a5a4a13a2",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A estrutura funcional da instalação distingue tratamento de efluentes da produção, drenagem aberta e fechada e vaso de slop, indicando interfaces operacionais próprias entre esses sistemas.",
          "trechos": [
            "E004f889a5a4a13a2:1383:2073"
          ],
          "condicoes": [
            "Contexto de divisão de trabalho e de sistemas de processo da unidade estudada"
          ],
          "limites": [
            "A fonte lista sistemas e equipamentos, mas não apresenta o mecanismo de segregação hidráulica entre eles"
          ]
        },
        {
          "proposicao": "A drenagem aberta aparece associada a tanque e linhas dedicadas, enquanto o slop vessel é apresentado separadamente, sugerindo separação física e funcional entre coleta de drenagem e acumulação/recuperação de correntes oleosas.",
          "trechos": [
            "E004f889a5a4a13a2:1383:2073"
          ],
          "condicoes": [
            "Inferência limitada à arquitetura nominada na fonte"
          ],
          "limites": [
            "A fonte não detalha se há segregação por classificação de área, pressão ou periculosidade"
          ]
        }
      ]
    },
    {
      "id": "Ecdb8e5f374915389",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O relatório destaca como desafio a garantia da disponibilidade e integridade de sistemas e equipamentos críticos, com contingência para falhas, capacitação em procedimentos críticos e controle de inspeções e manutenção.",
          "trechos": [
            "Ecdb8e5f374915389:0:699"
          ],
          "condicoes": [
            "Orientação geral da SSO/ANP no contexto de segurança operacional offshore"
          ],
          "limites": [
            "Não é requisito específico de drenagem nem detalha critérios de projeto"
          ]
        },
        {
          "proposicao": "Também é destacada a necessidade de planejamento e disponibilização de recursos para integridade de tubulações, equipamentos e estruturas, com desenvolvimento de indicadores e métricas para acompanhamento.",
          "trechos": [
            "Ecdb8e5f374915389:699:1397"
          ],
          "condicoes": [
            "Aplicável ao contexto de gestão da integridade e aprimoramento contínuo"
          ],
          "limites": [
            "A fonte não traz métricas específicas nem limites de aceitabilidade"
          ]
        },
        {
          "proposicao": "Em fiscalização de unidade offshore, a ANP registrou degradação e subdimensionamento de sistemas de drenagem aberta com transbordamento, associando esses desvios a risco grave e iminente para pessoas e meio ambiente.",
          "trechos": [
            "Ecdb8e5f374915389:1397:2091",
            "Ecdb8e5f374915389:2091:2370"
          ],
          "condicoes": [
            "Constatação vinculada ao caso específico da P-31 em 2023"
          ],
          "limites": [
            "É evidência de consequência operacional em caso real, não descrição completa de critério de dimensionamento"
          ]
        }
      ]
    },
    {
      "id": "E766f0de93462d15d",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A drenagem aberta de área classificada é recolhida por tubo de despejo/caisson, que também recebe correntes da drenagem aberta de área não classificada, onde ocorre separação bifásica.",
          "trechos": [
            "E766f0de93462d15d:0:699"
          ],
          "condicoes": [
            "Descrição do arranjo da P-18 segundo a fonte"
          ],
          "limites": [
            "A reunião de correntes classificada e não classificada é descritiva do caso e não vem acompanhada de avaliação explícita do risco de interligação"
          ]
        },
        {
          "proposicao": "Após a separação no caisson, a água enquadrada em TOG é descartada e o resíduo oleoso é enviado ao vaso de drenagem fechada/slop por bombeamento.",
          "trechos": [
            "E766f0de93462d15d:0:699"
          ],
          "condicoes": [
            "Descarga aquosa condicionada ao enquadramento em TOG"
          ],
          "limites": [
            "Os valores numéricos de TOG não aparecem preservados neste trecho"
          ]
        },
        {
          "proposicao": "O slop recebe rejeito oleoso do hidrociclone, correntes de drenagem fechada e aberta vindas do caisson e rejeito oleoso do skimmer, reinserindo essas correntes ao processo de separação de óleo.",
          "trechos": [
            "E766f0de93462d15d:0:699"
          ],
          "condicoes": [
            "No arranjo operacional descrito para a unidade"
          ],
          "limites": [
            "A própria fonte registra que a descrição do tratamento de água produzida não corresponde integralmente à realidade da P-18 por inoperância dos hidrociclones"
          ]
        }
      ]
    },
    {
      "id": "E52495a03cf552038",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No flotador a gás dissolvido, parte do gás acumulado no topo e parte da água tratada são recirculados; após contato sob pressão e posterior despressurização no vaso, formam-se bolhas microscópicas que arrastam agregados de óleo para a superfície, gerando resíduo oleoso coletado para o vaso de drenagem fechada.",
          "trechos": [
            "E52495a03cf552038:0:696"
          ],
          "condicoes": [
            "Aplicável ao equipamento do tipo gás dissolvido descrito na fonte"
          ],
          "limites": [
            "A fonte explica o mecanismo do flotador, não a classificação de drenagem como perigosa ou não perigosa"
          ]
        },
        {
          "proposicao": "Após o flotador, a água pode ser descartada diretamente no mar se estiver enquadrada nos padrões de descarte e se não houver reinjeção de água produzida na unidade; em plataformas fixas ou semissubmersíveis, o descarte ocorre por tubo de despejo/caisson abaixo da linha d’água.",
          "trechos": [
            "E52495a03cf552038:696:1387"
          ],
          "condicoes": [
            "Necessidade de enquadramento nos padrões de descarte",
            "Condição adicional de não haver reinjeção de água produzida na unidade"
          ],
          "limites": [
            "O valor numérico do padrão de TOG está parcialmente apagado na fonte e não pode ser reconstruído"
          ]
        },
        {
          "proposicao": "Em FPSOs, um tanque de carga pode ser usado como etapa adicional de separação gravitacional antes do descarte, aumentando a segurança contra derrame de resíduos oleosos; porém o acúmulo prolongado de água produzida em ambiente fechado pode favorecer BRS e geração de H2S, com toxicidade e corrosividade.",
          "trechos": [
            "E52495a03cf552038:696:1387",
            "E52495a03cf552038:1387:2074"
          ],
          "condicoes": [
            "Uso de tanque de carga no processo de separação do óleo presente na água produzida",
            "Períodos de baixa produção de água podem aumentar o tempo de residência"
          ],
          "limites": [
            "A fonte não detalha quais facilidades específicas são exigidas para mitigar o risco de H2S"
          ]
        }
      ]
    },
    {
      "id": "Ef215118b2aaed6c0",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No FPSO estudado, a água produzida removida no separador de alta pressão e no tratador eletrostático é encaminhada a sistema próprio de tratamento composto por hidrociclones, flotador e trocador de calor, com objetivo de adequação para descarte no mar.",
          "trechos": [
            "Ef215118b2aaed6c0:696:1396"
          ],
          "condicoes": [
            "Descrição do FPSO analisado no estudo"
          ],
          "limites": [
            "A fonte trata do fluxo principal de água produzida, não da drenagem aberta/fechada em detalhe"
          ]
        },
        {
          "proposicao": "A plataforma conta, além dos sistemas principais de processo, com drenagem aberta e fechada como sistemas essenciais ao funcionamento.",
          "trechos": [
            "Ef215118b2aaed6c0:696:1396"
          ],
          "condicoes": [
            "No contexto do FPSO analisado"
          ],
          "limites": [
            "A fonte apenas menciona esses sistemas, sem apresentar critérios de segregação"
          ]
        },
        {
          "proposicao": "A fonte associa a qualidade do óleo tratado a fatores de separação como viscosidade da emulsão óleo/água, o que é relevante para compreender interfaces entre tratamento de processo e correntes que podem seguir para sistemas de drenagem e slop em casos de ineficiência de separação.",
          "trechos": [
            "Ef215118b2aaed6c0:1396:2096",
            "Ef215118b2aaed6c0:2096:2184"
          ],
          "condicoes": [
            "No contexto de enquadramento do óleo quanto a sal e BSW"
          ],
          "limites": [
            "A relação com drenagem é indireta; a fonte não descreve encaminhamento dessas correntes para os sistemas de drenagem"
          ]
        }
      ]
    }
  ],
